// AccountBalance Account balance, credits, and unpaid charges are reported separately.
type AccountBalance struct {
	// Balance Prepaid funds in the account currency, excluding credits. May be negative after a payment
	// dispute. Outstanding charges are reported separately in due; this value is not a withdrawal quote.
	Balance          externalRef0.Money `json:"balance"`
	BillingAccountId int64              `json:"billing_account_id"`

	// CreditGroups Currently valid, unspent credit grouped by permitted use. Restrictions and
	// validity dates determine which charges a group can cover, so these groups are not a general
	// spendable balance and may differ from the recorded credits total.
	CreditGroups []CreditGroup `json:"credit_groups"`

	// Credits The recorded remaining credit, including restricted grants. It is not withdrawable
	// and is not part of balance. credit_groups describes currently valid credit by permitted use; a positive
	// credits balance does not imply that due is zero.
	Credits  externalRef0.Money `json:"credits"`
	Currency string             `json:"currency"`

	// Due Owed and not yet paid: metered usage that balance and applicable credit could not cover as it was
	// charged, and issued usage invoices still unpaid. The account is in arrears while this
	// is above zero. Topping up pays it on the next collection.
	Due externalRef0.Money `json:"due"`

	// RestrictedCredits The part of currently valid credit that only pays for what its restrictions allow, such as a single
	// service, a billing type or a first purchase. The rest of the valid credit pays for anything on the account.
	// Included in credits and therefore in total.
	RestrictedCredits externalRef0.Money `json:"restricted_credits"`

	// Total balance plus credits, the sum shown as the account's funds. Credits count at their recorded remaining
	// amount, including restricted grants that only pay for what they allow, so total is an upper bound of what
	// the account can pay with rather than a withdrawable amount. due is reported separately and is not subtracted.
	Total externalRef0.Money `json:"total"`
}

